
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_rge2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_rge2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.245409506243859e+00, -4.162847643020214e+00, -4.047237484120163e+00, -3.887257505941760e+00, -3.669630468097658e+00, -3.380794053441972e+00, -3.010863030992843e+00, -2.560946071907427e+00, -2.053575204615840e+00, -1.537809822277957e+00, -1.048402824733063e+00, -6.966768549369279e-01, -5.967377438530921e-01, -4.899839338571456e-01, -3.563118470340721e-01, -2.348839079428538e-01, -1.374679542880826e-01, -5.030859343717314e-02, -1.082141696338836e-02, -1.216216048873502e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


